async def wallet_index_reconcile(
    client: Client,
    request: WalletIndexReconcileRequest,
) -> WalletIndexReconcileResponse:
    """Reconcile a wallet's index with the chain's balance: `POST /v1/wallets/{id}/indexes/{asset}/reconcile`.

    Deletes the index's mined legs above the chain's final block and unsets its progress: its balances read null until the next indexing step reads the chain's balance at a final block, appends one `adjustment` leg of the difference and reads on from there. Pending legs stay. Corrects what indexing cannot see, such as ether a contract sent. Only on chains that read balances (Solana, Ethereum).
    """
    return WalletIndex.from_json(await client.send(request))


