# The output of `wallets_create`.
WalletsCreateResponse: TypeAlias = Wallet


async def wallets_create(
    client: Client,
    request: WalletsCreateRequest,
) -> WalletsCreateResponse:
    """Import a wallet's key, watch an address, or generate a wallet, in one configured network: `POST /v1/wallets`.

    With `secret`, imports a raw private key and keeps it; with `address` too, the key must derive that address. With `address` alone, watches it without its key. With neither, generates a key and keeps it; retrying makes another wallet. The wallet is created without indexes (`POST /v1/wallets/{id}/index`). An address already kept answers its wallet as is (200), except that importing the key of a watch-only wallet keeps the key, and an `external_id` is kept on a wallet that has none; another `external_id` than the kept one is refused (409); its tags and indexes stay.
    """
    return Wallet.from_json(await client.send(request))


